import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

describe('ask-for-approval-flow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Round-Trip Test: ask-for-approval-flow
     *
     * XML Source: sys_hub_flow_e1afd5897ba84f678690a7736df8464d.xml
     * Fluent Source: ask-for-approval-action-datapills-examples.now.ts
     *
     * Flow Name: Test flow for ask for approval action fluent
     * Description: Flow with record.created trigger, askForApproval action with complex approval rules, and if logic
     *
     * This test validates:
     * - XML → Fluent transformation generates correct TypeScript code
     * - Fluent → XML transformation preserves all flow data
     * - Round-trip maintains data integrity
     *
     * Flow Structure:
     * - Type: Flow
     * - Trigger: record.created on incident table
     * - Flow Variables: sampleField1 (StringColumn, mandatory: true)
     * - Actions:
     *   1. log - initial log message
     *   2. askForApproval - with complex approval rules (OR/AND conditions, multiple rule types)
     * - Flow Logic: if condition checking approval_state with nested log action
     *
     * Features: Record trigger, flow variables, askForApproval with approval rules, if logic, datapills
     */
    test.skip('ask-for-approval-flow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_e1afd5897ba84f678690a7736df8464d.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Validate imports
        expect(fluentContent).toContain('import {')
        expect(fluentContent).toContain('Flow')
        expect(fluentContent).toContain('wfa')
        expect(fluentContent).toContain('trigger')
        expect(fluentContent).toContain('action')

        // Validate flow definition
        expect(fluentContent).toContain('Flow(')
        expect(fluentContent).toContain("name: 'Test flow for ask for approval action fluent'")

        // Validate flow variables
        expect(fluentContent).toContain('flowVariables:')
        expect(fluentContent).toContain('sampleField1: StringColumn(')
        expect(fluentContent).toContain("label: 'Sample Field 1'")
        expect(fluentContent).toContain('mandatory: true')

        // Validate trigger
        expect(fluentContent).toContain('wfa.trigger(')
        expect(fluentContent).toContain('trigger.record.created')
        expect(fluentContent).toContain("table: 'incident'")
        // Validate additional trigger parameters
        expect(fluentContent).toContain('run_on_extended:')
        expect(fluentContent).toContain('run_when_setting:')
        expect(fluentContent).toContain('run_flow_in:')

        // Validate Action 1: log (stored in actionInstance_1)
        expect(fluentContent).toContain('const actionInstance_1 = wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain("log_message: 'printed this message'")

        // Validate Action 2: askForApproval (stored in actionInstance_2)
        expect(fluentContent).toContain('const actionInstance_2 = wfa.action(')
        expect(fluentContent).toContain('action.core.askForApproval')
        expect(fluentContent).toContain("annotation: 'Ask for approval'")
        expect(fluentContent).toContain('record: wfa.dataPill(')
        expect(fluentContent).toContain('_params.trigger.current')
        expect(fluentContent).toContain("'reference'")
        expect(fluentContent).toContain("table: 'sys_user'")
        expect(fluentContent).toContain("approval_reason: 'Test approval reason'")
        expect(fluentContent).toContain("approval_field: 'approval'")
        expect(fluentContent).toContain("journal_field: 'approval_history'")
        expect(fluentContent).toContain("due_date: ''")

        // Validate approval rules structure (stored as object literal)
        expect(fluentContent).toContain('approval_conditions:')
        expect(fluentContent).toContain("conditionType: 'OR'")
        expect(fluentContent).toContain('ruleSets:')
        expect(fluentContent).toContain("action: 'Approves'")
        expect(fluentContent).toContain("action: 'Rejects'")
        expect(fluentContent).toContain("conditionType: 'AND'")

        // Validate approval rule types
        expect(fluentContent).toContain("ruleType: 'Any'")
        expect(fluentContent).toContain("ruleType: 'All'")
        expect(fluentContent).toContain("ruleType: 'Res'")
        expect(fluentContent).toContain("ruleType: 'Count'")
        expect(fluentContent).toContain('count: 3')
        expect(fluentContent).toContain("ruleType: 'Percent'")
        expect(fluentContent).toContain('percent: 40')

        // Validate datapills in approval rules
        expect(fluentContent).toContain('wfa.dataPill(_params.trigger.current.manager.city')
        expect(fluentContent).toContain('wfa.dataPill(_params.flowVariables.sampleField1')
        expect(fluentContent).toContain('wfa.dataPill(actionInstance_1.__action_status__')

        // Validate if logic
        expect(fluentContent).toContain('wfa.flowLogic.if(')
        expect(fluentContent).toContain("annotation: 'If Approved'")
        expect(fluentContent).toContain('wfa.dataPill(actionInstance_2.approval_state')
        expect(fluentContent).toContain('=approved')

        // Validate nested log action in if block
        expect(fluentContent).toContain('log_message: wfa.dataPill(actionInstance_2.approval_state')

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)?.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        expect(mergedRecords['sys_hub_flow']).toBeDefined()

        // Validate flow record
        const flows = mergedRecords['sys_hub_flow']
        const flow = flows.find((f: any) => f.name === 'Test flow for ask for approval action fluent')
        expect(flow).toBeDefined()
        expect(flow.type).toBe('flow')
        expect(flow.generation_source).toBe('fluent')
        expect(flow.run_as).toBe('system')

        // Validate flow variables
        if (mergedRecords['sys_hub_flow_variable']) {
            const flowVars = mergedRecords['sys_hub_flow_variable'].filter((v: any) => v.model === flow.sys_id)
            expect(flowVars.length).toBe(1) // Exact count: sampleField1

            const sampleField1Var = flowVars.find((v: any) => v.element === 'sampleField1')
            expect(sampleField1Var).toBeDefined()
            expect(sampleField1Var.label).toBe('Sample Field 1')
            expect(sampleField1Var.internal_type).toBe('string')
            expect(sampleField1Var.mandatory).toBe(true)
        }

        // Validate trigger
        if (mergedRecords['sys_hub_trigger_instance_v2']) {
            const triggers = mergedRecords['sys_hub_trigger_instance_v2'].filter((t: any) => t.flow === flow.sys_id)
            expect(triggers.length).toBe(1) // Exact count

            const trigger = triggers[0]
            expect(trigger).toBeDefined()
            expect(trigger.trigger_type).toBeDefined()

            // Decompress and validate trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const triggerVal = (name: string) => findInput(triggerInputs, name)?.value

            expect(triggerVal('table')).toBe('incident')
            // Validate additional trigger parameters
            expect(triggerVal('run_on_extended')).toBeDefined()
            expect(triggerVal('run_when_setting')).toBeDefined()
            expect(triggerVal('run_flow_in')).toBeDefined()
            expect(triggerVal('condition')).toBeDefined()
            expect(triggerVal('run_when_user_setting')).toBeDefined()
        }

        // Validate actions
        if (mergedRecords['sys_hub_action_instance_v2']) {
            const actions = mergedRecords['sys_hub_action_instance_v2'].filter((a: any) => a.flow === flow.sys_id)
            expect(actions.length).toBeGreaterThanOrEqual(2) // At least log and askForApproval

            // Validate log action
            const logAction = actions.find((a: any) => a.comment?.includes('printed this message') || !a.comment)
            if (logAction) {
                expect(logAction.action_type).toBeDefined()

                const logValues = unzipInputArray(logAction.values)
                const logVar = (name: string) => findInput(logValues, name)?.value

                expect(logVar('log_level')).toBe('info')
                expect(logVar('log_message')).toBe('printed this message')
            }

            // Validate askForApproval action
            const askForApprovalAction = actions.find((a: any) => a.comment?.includes('Ask for approval'))
            expect(askForApprovalAction).toBeDefined()
            expect(askForApprovalAction.action_type).toBeDefined()

            const approvalValues = unzipInputArray(askForApprovalAction.values)
            const approvalVar = (name: string) => findInput(approvalValues, name)?.value

            // Validate basic approval parameters
            expect(approvalVar('table')).toBe('sys_user')
            expect(approvalVar('approval_reason')).toBe('Test approval reason')
            expect(approvalVar('approval_field')).toBe('approval')
            expect(approvalVar('journal_field')).toBe('approval_history')
            expect(approvalVar('due_date')).toBeDefined()

            // Validate record datapill is present
            const recordValue = approvalVar('record')
            expect(recordValue).toBeDefined()
            expect(recordValue).toMatch(/\{\{.*current.*\}\}/)

            // Validate approval_conditions contains complex rules
            const approvalConditions = approvalVar('approval_conditions')
            expect(approvalConditions).toBeDefined()
            // Should contain OR/AND structure and various rule types
            expect(approvalConditions).toContain('OR')
            expect(approvalConditions).toContain('AND')
            expect(approvalConditions).toContain('Approves')
            expect(approvalConditions).toContain('Rejects')
            // Validate all rule types are present
            expect(approvalConditions).toContain('Any')
            expect(approvalConditions).toContain('All')
            expect(approvalConditions).toContain('Res')
            expect(approvalConditions).toContain('Count')
            expect(approvalConditions).toContain('Percent')
            // Validate datapills in approval conditions
            expect(approvalConditions).toMatch(/\{\{.*manager.*city.*\}\}/)
            expect(approvalConditions).toMatch(/\{\{.*sampleField1.*\}\}/)
            expect(approvalConditions).toMatch(/\{\{.*__action_status__.*\}\}/)
        }

        // Validate if logic
        if (mergedRecords['sys_hub_flow_logic_instance_v2']) {
            const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2'].filter(
                (fl: any) => fl.flow === flow.sys_id
            )

            const ifLogic = flowLogicInstances.find((fl: any) => fl.comment?.includes('If Approved'))
            expect(ifLogic).toBeDefined()
            expect(ifLogic.logic_definition).toBeDefined()

            // Decompress and validate if condition
            const ifValues = unzipInputArray(ifLogic.values)
            const ifVar = (name: string) => findInput(ifValues, name)?.value

            const condition = ifVar('condition')
            expect(condition).toBeDefined()
            // Condition should check approval_state = approved with datapill
            expect(condition).toMatch(/\{\{.*approval_state.*\}\}/)
            expect(condition).toContain('=approved')
        }

        // Validate nested action in if block
        if (mergedRecords['sys_hub_action_instance_v2']) {
            const actions = mergedRecords['sys_hub_action_instance_v2'].filter((a: any) => a.flow === flow.sys_id)

            // Find nested log action (should have no comment or different comment)
            const nestedLogActions = actions.filter((a: any) => {
                const values = unzipInputArray(a.values)
                const logMsg = findInput(values, 'log_message')?.value
                return logMsg && logMsg.includes('approval_state')
            })

            if (nestedLogActions.length > 0) {
                const nestedLog = nestedLogActions[0]
                const nestedLogValues = unzipInputArray(nestedLog.values)
                const nestedLogVar = (name: string) => findInput(nestedLogValues, name)?.value

                expect(nestedLogVar('log_level')).toBe('info')
                const nestedLogMessage = nestedLogVar('log_message')
                expect(nestedLogMessage).toBeDefined()
                // Log message should contain approval_state datapill
                expect(nestedLogMessage).toMatch(/\{\{.*approval_state.*\}\}/)
            }
        }
    })
})
